    public function add(){ $this->load->language('extension/probg_blog/article');$this->document->setTitle($this->language->get('heading_title'));$this->load->model('extension/probg_blog/article');if($this->request->server['REQUEST_METHOD']==='POST'&&$this->validateForm()){ $this->model_extension_probg_blog_article->addArticle($this->request->post);$this->session->data['success']=$this->language->get('text_success');$this->response->redirect($this->url->link('extension/probg_blog/article','user_token='.$this->session->data['user_token'].$this->listUrl(),true)); }$this->getForm(); }
