        $filter=array('filter_title'=>$f_title,'filter_category_id'=>$f_cat,'filter_status'=>$f_status,'filter_date_added_from'=>$f_from,'filter_date_added_to'=>$f_to,'sort'=>$sort,'order'=>$order,'start'=>($page-1)*(int)$this->config->get('config_limit_admin'),'limit'=>(int)$this->config->get('config_limit_admin'));$total=$this->model_extension_probg_blog_article->getTotalArticles($filter);$results=$this->model_extension_probg_blog_article->getArticles($filter);$this->load->model('tool/image');$data['articles']=array();foreach($results as $r){$thumb=(!empty($r['image'])&&is_file(DIR_IMAGE.$r['image']))?$this->model_tool_image->resize($r['image'],40,40):$this->model_tool_image->resize('no_image.png',40,40);$data['articles'][]=array('article_id'=>$r['article_id'],'thumb'=>$thumb,'title'=>$r['title'],'category'=>$r['category'],'sort_order'=>$r['sort_order'],'status'=>$r['status']?$this->language->get('text_enabled'):$this->language->get('text_disabled'),'date_added'=>date($this->language->get('date_format_short'),strtotime($r['date_added'])),'date_modified'=>date($this->language->get('date_format_short'),strtotime($r['date_modified'])),'edit'=>$this->url->link('extension/probg_blog/article/edit','user_token='.$this->session->data['user_token'].'&article_id='.(int)$r['article_id'].$this->listUrl(),true));}
        $this->baseData($data);foreach(array('text_list','text_no_results','text_confirm','text_all','text_enabled','text_disabled','column_image','column_id','column_title','column_category','column_sort_order','column_status','column_date_added','column_date_modified','column_action','entry_title','entry_category','entry_status','entry_date_added_from','entry_date_added_to','button_add','button_delete','button_edit','button_filter','button_settings') as $k)$data[$k]=$this->language->get($k);$data['add']=$this->url->link('extension/probg_blog/article/add','user_token='.$this->session->data['user_token'].$this->listUrl(),true);$data['delete']=$this->url->link('extension/probg_blog/article/delete','user_token='.$this->session->data['user_token'].$this->listUrl(),true);$data['settings']=$this->url->link('extension/module/probg_blog','user_token='.$this->session->data['user_token'],true);$data['filter_title']=$f_title;$data['filter_category_id']=$f_cat;$data['filter_status']=$f_status;$data['filter_date_added_from']=$f_from;$data['filter_date_added_to']=$f_to;$data['sort']=$sort;$data['order']=$order;$data['selected']=isset($this->request->post['selected'])?(array)$this->request->post['selected']:array();$this->load->model('extension/probg_blog/category');$data['categories']=$this->model_extension_probg_blog_category->getCategories(array('sort'=>'cd.title','order'=>'ASC'));
