    protected function getForm(){
        $data=array();$this->baseData($data);foreach(array('text_add','text_edit','text_content','text_data','text_images','text_main_image','text_additional_images','text_enabled','text_disabled','text_automatic','entry_title','entry_short_description','entry_description','entry_meta_title','entry_meta_description','entry_meta_keyword','entry_seo_keyword','entry_category','entry_image','entry_sort_order','entry_status','entry_date_added','entry_date_modified','help_seo_keyword','button_save','button_cancel','button_add_image','button_remove') as $k)$data[$k]=$this->language->get($k);$id=isset($this->request->get['article_id'])?(int)$this->request->get['article_id']:0;$data['text_form']=$id?$this->language->get('text_edit'):$this->language->get('text_add');$data['error_warning']=isset($this->error['warning'])?$this->error['warning']:'';$data['error_title']=isset($this->error['title'])?$this->error['title']:array();$data['error_seo_keyword']=isset($this->error['seo_keyword'])?$this->error['seo_keyword']:array();$data['error_category']=isset($this->error['category'])?$this->error['category']:'';$data['action']=$this->url->link($id?'extension/probg_blog/article/edit':'extension/probg_blog/article/add','user_token='.$this->session->data['user_token'].($id?'&article_id='.$id:'').$this->listUrl(),true);$data['cancel']=$this->url->link('extension/probg_blog/article','user_token='.$this->session->data['user_token'].$this->listUrl(),true);$info=$id?$this->model_extension_probg_blog_article->getArticle($id):array();$this->load->model('localisation/language');$data['languages']=$this->model_localisation_language->getLanguages();$data['article_description']=isset($this->request->post['article_description'])?$this->request->post['article_description']:($id?$this->model_extension_probg_blog_article->getArticleDescriptions($id):array());$this->load->model('extension/probg_blog/category');$data['categories']=$this->model_extension_probg_blog_category->getCategories(array('sort'=>'c