    }
    protected function validateForm(){if(!$this->user->hasPermission('modify','extension/probg_blog/article'))$this->error['warning']=$this->language->get('error_permission');$this->load->model('extension/probg_blog/category');$cat=isset($this->request->post['category_id'])?(int)$this->request->post['category_id']:0;if(!$cat||!$this->model_extension_probg_blog_category->getCategory($cat))$this->error['category']=$this->language->get('error_category');$this->load->model('localisation/language');$id=isset($this->request->get['article_id'])?(int)$this->request->get['article_id']:0;foreach($this->model_localisation_language->getLanguages() as $lang){$lid=(int)$lang['language_id'];$v=isset($this->request->post['article_description'][$lid])?$this->request->post['article_description'][$lid]:array();$title=isset($v['title'])?trim($v['title']):'';if(utf8_strlen($title)<1||utf8_strlen($title)>255)$this->error['title'][$lid]=$this->language->get('error_title');$kw=isset($v['seo_keyword'])?trim($v['seo_keyword']):'';if($kw!==''&&(!preg_match('/^[\p{L}\p{N}_-]+$/u',$kw)||$this->model_extension_probg_blog_article->getSeoUrlByKeyword($kw,$lid,$id)))$this->error['seo_keyword'][$lid]=$this->language->get('error_seo_keyword_exists');}if($this->error&&!isset($this->error['warning']))$this->error['warning']=$this->language->get('error_warning');return !$this->error;}
